import java.util.Arrays;

class Solution {
    public int maxPathScore(int[][] grid, int k) {
            int m = grid.length;
                    int n = grid[0].length;

                            // dp[i][j][c] stores the maximum score at cell (i, j) with exact total cost c
                                    int[][][] dp = new int[m][n][k + 1];
                                            
                                                    for (int i = 0; i < m; i++) {
                                                                for (int j = 0; j < n; j++) {
                                                                                Arrays.fill(dp[i][j], -1);
                                                                                            }
                                                                                                    }

                                                                                                            // Base case: Top-left cell (0, 0)
                                                                                                                    int startVal = grid[0][0];
                                                                                                                            int startCost = startVal == 0 ? 0 : 1;
                                                                                                                                    int startScore = startVal;

                                                                                                                                            if (startCost <= k) {
                                                                                                                                                        dp[0][0][startCost] = startScore;
                                                                                                                                                                }

                                                                                                                                                                        for (int i = 0; i < m; i++) {
                                                                                                                                                                                    for (int j = 0; j < n; j++) {
                                                                                                                                                                                                    int cellVal = grid[i][j];
                                                                                                                                                                                                                    int cost = cellVal == 0 ? 0 : 1;
                                                                                                                                                                                                                                    int score = cellVal;

                                                                                                                                                                                                                                                    for (int c = 0; c <= k; c++) {
                                                                                                                                                                                                                                                                        // Skip unvisited states
                                                                                                                                                                                                                                                                                            if (dp[i][j][c] == -1) continue;

                                                                                                                                                                                                                                                                                                                // Move Right -> (i, j + 1)
                                                                                                                                                                                                                                                                                                                                    if (j + 1 < n && c + cost <= k) {
                                                                                                                                                                                                                                                                                                                                                            dp[i][j + 1][c + cost] = Math.max(dp[i][j + 1][c + cost], dp[i][j][c] + score);
                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                    // Move Down -> (i + 1, j)
                                                                                                                                                                                                                                                                                                                                                                                                                        if (i + 1 < m && c + cost <= k) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                dp[i + 1][j][c + cost] = Math.max(dp[i + 1][j][c + cost], dp[i][j][c] + score);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Find the maximum score achievable at cell (m - 1, n - 1) within cost k
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int maxScore = -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int lastVal = grid[m - 1][n - 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int lastCost = lastVal == 0 ? 0 : 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int lastScore = lastVal;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (int c = 0; c + lastCost <= k; c++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (dp[m - 1][n - 1][c] != -1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    maxScore = Math.max(maxScore, dp[m - 1][n - 1][c] + lastScore);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return maxScore;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }